# Analyze each changed pair to find minimal edits
inputs = ['bd', 'beba', 'wdxgzz', 'cjdcay', 'ihg']
outputs = ['bj', 'beba', 'wjxgzz', 'cjjcacka', 'idcg']

# Let's manually examine each changed pair
changed_pairs = [
    (0, 'bd', 'bj'),
    (2, 'wdxgzz', 'wjxgzz'), 
    (3, 'cjdcay', 'cjjcacka'),
    (4, 'ihg', 'idcg')
]

for idx, inp, outp in changed_pairs:
    print(f"\nPair {idx}: '{inp}' -> '{outp}'")

    # Find differences character by character
    min_len = min(len(inp), len(outp))
    diff_positions = []

    for i in range(min_len):
        if inp[i] != outp[i]:
            diff_positions.append(i)

    # Check if it's a simple substitution or insertion/deletion
    if len(inp) == len(outp):
        # Same length - substitution
        for i in range(len(inp)):
            if inp[i] != outp[i]:
                print(f"  Position {i}: '{inp[i]}' -> '{outp[i]}'")
    elif len(inp) > len(outp):
        # Deletion
        print(f"  Deleted characters at positions: {diff_positions}")
    else:
        # Insertion  
        print(f"  Inserted characters at positions: {diff_positions}")

